from collections import deque
def comps(g):
    n=len(g);m=len(g[0]);seen=set();out=[]
    for r in range(n):
        for c in range(m):
            if g[r][c]==0 and (r,c) not in seen:
                q=deque([(r,c)]);seen.add((r,c));cells=[]
                while q:
                    a,b=q.popleft();cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<n and 0<=y<m and g[x][y]==0 and (x,y) not in seen:
                                seen.add((x,y));q.append((x,y))
                out.append(cells)
    return out
