def solve(g):
    n=len(g);m=len(g[0]);out=[r[:] for r in g]
    for r in range(n):
        for c in range(m):
            if g[r][c]==0:
                # BFS 4-connectivity
                q=deque([(r,c)]);seen={(r,c)};cells=[]
                while q:
                    a,b=q.popleft();cells.append((a,b))
                    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<n and 0<=y<m and g[x][y]==0 and (x,y) not in seen:
                            seen.add((x,y));q.append((x,y))
                if len(cells)>=2:
                    for (a,b) in cells: out[a][b]=8
    return out
